  meals_people_title: 'People',
  meals_mig17_title: 'Without an employee reference, this invitation produces a membership that cannot be labelled later.',
  meals_mig17_body: 'The reference can only be captured here, at the invitation. A membership claimed without one can never acquire it: the invitation is spent, and the lines of a finalized monthly statement are locked. The person then appears as a bare identifier on every line of that company\'s bill, for good.',
  meals_mig17_ack: 'I understand this invitation produces a membership that will appear as a bare identifier on every future monthly statement, and that it cannot be corrected later.',
