  meals_token_not_sent_title: 'Nothing has been sent.',
  meals_token_not_sent_body: 'Okam has no way to deliver this token — no email, no SMS. It exists here and nowhere else. For the invitation to reach anybody you have to pass the token on yourself, through a channel you trust.',
