  meals_token_recipient: 'Intended for {contact} as {role}. Expires {expires}.',
  meals_token_bearer_note: 'The token works once, and whoever claims it must be signed in as the contact you named. A forwarded token is refused.',
  meals_token_claim_screen: 'Whoever you give the code to redeems it themselves at {link}. They paste the code in there and sign in. Okam sends them nothing, so the address has to travel with the code.',
