  wfpl_correct_title: 'Correct the entry for {name}',
  wfpl_correct_note: 'A correction changes nothing. It records a new entry that supersedes the old one and shows who corrected it and when; the old entry is retained exactly as it was. The times are the clock at the workplace itself.',
  wfpl_correct_start: 'Start of the working day',
  wfpl_correct_end: 'End of the working day',
  wfpl_correct_no_departure: 'No departure recorded',
  wfpl_correct_save: 'Record the correction',
