  wfpl_correct_failed: 'The correction was not recorded.',
  wfpl_correct_start_invalid: 'The start needs both a date and a time.',
  wfpl_correct_end_invalid: 'The end needs both a date and a time, or must be marked as no departure recorded.',
  wfpl_correct_order_invalid: 'The departure must be after the arrival.',
  wfpl_summary_today: '{count} entries this day. {open} are at the workplace now.',
  wfpl_summary_past: '{count} entries this day. {open} of them have no end time recorded.',
  wfpl_summary_rows_only: '{count} entries this day.',
  wfpl_asof: 'Read from the server {date} {time} ({zone}).',
  wfpl_retain_until: 'The personnel list must be kept in Norway until {date} — three years and six months after the end of the accounting year.',
  wfpl_corrections: '{count} of the entries have been corrected. Who corrected them and when is in the note column.',

  // Market and time zone (StoreMarketCard). Currency is NEVER a field: it derives from the market.
