  sm_loading: 'Reading the market …',
  sm_no_store: 'Select a store to see its market.',
  sm_read_failed: 'We could not read this store\'s market. That does not mean the store has no market — we simply do not know what it says.',
  sm_field_country: 'Country',
  sm_field_currency: 'Currency',
  sm_field_zone: 'Time zone',
  sm_not_set: 'Not set',
  sm_choose: 'Choose …',
  sm_currency_is_derived: 'The currency follows from the country and is not set here.',
  sm_zone_is_platform_default: 'the platform default',
  sm_no_country_warning: 'This store has no country. The country selects the working-time rule pack, so without one the schedule refuses every week you try to publish.',
  sm_no_rulepack_warning: 'This store is in {country}, and there is no working-time rule pack for that country. The schedule will refuse every week you try to publish.',
  sm_zone_fallback_warning: 'No time zone has been chosen for this venue. Its business days are currently cut at {zone} because that is the platform default — not because anyone decided it for this store. If the venue is somewhere else, its days are being split at the wrong moment.',
  sm_country_help: 'The list is the markets that have a working-time rule pack. Today that is Norway only. Another country can technically be stored, but the schedule would then refuse every week — so it is not offered here.',
  sm_country_not_offered: '{country} (the country this store is in now)',
  sm_choice_no_rulepack_warning: 'There is no working-time rule pack for {country}. Saving this will set the market, but the schedule will refuse every week you try to publish.',
  sm_currency_consequence: 'The currency becomes {currency}',
  sm_currency_consequence_unknown: 'The platform decides the currency from the country when you save.',
  sm_zone_placeholder: 'Europe/Oslo',
  sm_zone_help: 'A time-zone id the platform can load, for example Europe/Oslo. The country does not determine it — several countries span several zones, so it has to be chosen.',
  sm_zone_help_current_default: 'Choose none and the days keep being cut at {zone}.',
  sm_saving: 'Saving …',
