  gr_guest_refused_detail: 'The server said: {detail}',
  gr_guest_refused_address_required: 'We are missing the email address.',
  gr_guest_refused_consent_text_unknown: 'The consent wording on this page is no longer current. Reload the page and we will fetch the wording that applies now.',
  gr_guest_refused_not_found: 'This is not here.',
  gr_guest_refused_token_invalid: 'The link has been used or has expired.',
  gr_guest_refused_session_invalid: 'The session has expired.',
  gr_guest_refused_scope_mismatch: 'This link does not cover what you tried to change.',
